from pathlib import Path
import re
root=Path('.')
home=(root/'index.html').read_text(encoding='utf-8')
footer=home[home.index('<footer'):home.index('<script src=')]
nav=home[home.index('<nav'):home.index('</nav>')+6]
form='''<section class="section enquiry-section" id="inquiry"><div class="wrap enquiry-layout"><div><p class="eyebrow">Let's start a conversation</p><h2 class="section-title">Make an<br><em>Inquiry.</em></h2><p>Tell us what you need. Our Kimberley team can help with minerals, bulk requirements, mining partnerships and investment enquiries.</p><a class="enquiry-email" href="mailto:info@triple7holdings.co.za">info@triple7holdings.co.za</a><p class="enquiry-note">This form opens your email app with your enquiry ready to send.</p></div><form class="enquiry-form" data-enquiry-form><div class="enquiry-fields"><label>Your name<input name="name" autocomplete="name" maxlength="120" required></label><label>Email address<input name="email" type="email" autocomplete="email" maxlength="200" required></label><label>Phone <span>(optional)</span><input name="phone" type="tel" autocomplete="tel" maxlength="60"></label><label>I'm interested in<select name="interest"><option>General enquiry</option><option>Diamonds</option><option>Gold</option><option>Bulk commodities</option><option>Mining partnerships</option><option>Investment</option></select></label></div><label>Your enquiry<textarea name="message" rows="5" maxlength="4000" required placeholder="Product, quantity, destination or project details…"></textarea></label><button class="btn btn-solid" type="submit">Make an Inquiry ↗</button><p class="enquiry-status" role="status"></p></form></div></section>'''
highlights=[('About','The company behind the stones.','Our story, expertise and commitment to communities.','about.html','csr-son.jpg'),('Minerals','Explore natural value.','Discover diamonds and gold, and discuss your requirements.','minerals.html','rough-stone.jpg'),('Trade','Your next acquisition.','Browse lots and speak directly with our Trade Desk.','trade.html','lots/G-2201.jpg'),('Invest','Build a shared future.','Learn about our investment approach and project opportunities.','investors.html','hero-banner2.jpg'),('Mine Projects','Where the journey begins.','Explore Bucklands and Longlands in the Northern Cape.','mine-projects.html','mines/bucklands-wide.jpg')]
summary='<section class="section home-summary"><div class="wrap"><div class="summary-heading"><p class="eyebrow">Discover Triple 7 Holdings</p><h2 class="section-title">One company.<br><em>A world of possibility.</em></h2><p>Explore the people, resources and opportunities that shape our business.</p></div><div class="highlight-grid">'+''.join(f'<a class="highlight-card reveal" href="{url}"><img src="images/{img}" alt="" loading="lazy"><div><span class="eyebrow">0{i+1} / {name}</span><h3>{title}</h3><p>{desc}</p><span class="text-link">Explore {name} ↗</span></div></a>' for i,(name,title,desc,url,img) in enumerate(highlights))+'</div></div></section>'
bulk='''<section class="section bulk-section" id="bulk-commodities"><div class="wrap bulk-layout"><figure><img src="images/mines/bucklands-wide.jpg" alt="Material handling equipment at a mining operation" loading="lazy"></figure><div><p class="eyebrow">Bulk Commodities</p><h2 class="section-title">Your requirements.<br><em>Our next conversation.</em></h2><p>Discuss your bulk commodity needs with Triple 7 Holdings. Share the material, specification, quantity and delivery destination so our team can review your enquiry.</p><dl class="bulk-details"><div><dt>01</dt><dd>Material &amp; specification</dd></div><div><dt>02</dt><dd>Quantity &amp; delivery schedule</dd></div><div><dt>03</dt><dd>Destination &amp; commercial requirements</dd></div></dl><a href="#inquiry" class="btn btn-solid" data-inquiry-interest="Bulk commodities">Inquire about bulk supply ↗</a></div></div></section>'''
services=[('Mining','Where the journey begins','Recovering natural rough diamonds from our own and partnered mining operations across Southern Africa.','live-operations.jpg'),('Processing','From earth to opportunity','Separating diamonds from recovered material and preparing them for sorting.','mines/bucklands-wide.jpg'),('Sorting','Every stone has a story','Understanding each stone’s characteristics and preparing suitable parcels.','rough-stone.jpg'),('Cut & Polish','Revealing natural brilliance','Preparing selected stones for cutting and polishing to bring their natural qualities into focus.','lots/D-1048.jpg'),('Sales','A personal path to purchase','Browse diamond and gold lots and discuss commercial terms with our Kimberley desk.','lots/G-2201.jpg')]
offers='<section class="section editorial-offer" id="services"><div class="wrap"><div class="offer-heading"><p class="eyebrow">What We Offer</p><h2 class="section-title">Expertise at every stage.</h2><p>From recovery to the Trade Desk, discover the work behind every stone.</p></div><div class="offer-card-grid">'+''.join(f'<article class="offer-card reveal"><div class="offer-card-image"><img src="images/{img}" alt="{name} — {title}" loading="lazy"><span>0{i+1}</span></div><div class="offer-card-copy"><p class="eyebrow">{name}</p><h3>{title}</h3><p>{desc}</p><a class="text-link" href="about.html#services">Discover our expertise ↗</a></div></article>' for i,(name,title,desc,img) in enumerate(services))+'</div></div></section>'
home=home.replace('</header>','</header>'+summary,1)
home=re.sub(r'<section class="section offer-section">.*?</section>',offers,home, count=1,flags=re.S)
home=home.replace('<section class="stats-band home-footprint">',bulk+'<section class="stats-band home-footprint">',1)
home=home.replace('<footer',form+'<footer',1)
home=home.replace('<a href="trade.html" class="btn btn-solid">Trade</a>','<a href="#inquiry" class="btn btn-solid">Make an Inquiry</a>',1)
home=home.replace('<header class="hero">','<main id="main-content"><header class="hero">',1).replace('<footer','</main><footer',1)
(root/'index.html').write_text(home,encoding='utf-8')
about=(root/'about.html').read_text(encoding='utf-8')
about=about.replace('<section class="section offer-section">','<section class="section offer-section" id="services">')
company='''<section class="section company-overview" id="company-overview"><div class="wrap"><p class="eyebrow">The complete picture</p><h2 class="section-title">Our business, connected.</h2><div class="company-overview-grid"><article><h3>Minerals &amp; trade</h3><p>Our business connects natural diamonds, processing and trade. Explore rough and polished diamonds and gold through the Kimberley Trade Desk, request a quote and discuss terms directly with our team.</p><a href="minerals.html" class="text-link">Explore Minerals ↗</a></article><article><h3>Bulk commodity enquiries</h3><p>For bulk requirements, share the material, specification, quantity and destination. Our team will discuss the requirement and confirm what can be offered.</p><a href="index.html#bulk-commodities" class="text-link">Discuss bulk commodities ↗</a></article><article><h3>Mine projects &amp; partnerships</h3><p>Bucklands in the Douglas area and Longlands in the Northern Cape form our two mine projects. Explore the projects and contact us to discuss partnerships or supporting information.</p><a href="mine-projects.html" class="text-link">Explore Mine Projects ↗</a></article></div></div></section>'''
about=about.replace('<section class="about-footprint"',company+'<section class="about-footprint"',1)
(root/'about.html').write_text(about,encoding='utf-8')
head=home[:home.index('<body')].replace('Triple 7 Holdings — Diamond Mining, Kimberley','Minerals — Triple 7 Holdings').replace('Triple 7 Holdings mines, sorts, and supplies natural, ethically-sourced diamonds from our Southern African projects.','Explore natural diamonds and gold with Triple 7 Holdings. Contact our Kimberley team about specifications and availability.')
mineralbody='''<main id="main-content"><header class="pagehead"><div class="pagehead-media"><img src="images/rough-stone.jpg" alt="Natural rough diamond"></div><div class="wrap"><p class="eyebrow on-dark">Our Minerals</p><h1 class="pagehead-title">Natural resources.<br><em>Considered possibilities.</em></h1><p class="pagehead-sub">Discover diamonds and gold through our Kimberley Trade Desk.</p></div></header><section class="section"><div class="wrap"><div class="summary-heading"><p class="eyebrow">Explore the collection</p><h2 class="section-title">From the ground.<br><em>To your requirements.</em></h2><p>Speak with our team about current listings, product specifications and supporting documentation.</p></div><div class="mineral-grid">'''
for name,img,description,url in [('Diamonds','rough-stone.jpg','Natural, untreated diamonds from our own and partnered operations. Explore rough and polished lots and discuss characteristics, parcel requirements and documentation with our team.','diamond'),('Gold','lots/G-2201.jpg','Explore gold lots through our Trade Desk. Discuss the form, purity, quantity and available assay information for the listing that interests you.','gold')]:
 mineralbody+=f'<article class="mineral-card reveal"><img src="images/{img}" alt="{name}" loading="lazy"><div><p class="eyebrow">{ "Natural stones" if name=="Diamonds" else "Precious metals"}</p><h2>{name}</h2><p>{description}</p><a href="trade.html?commodity={url}" class="btn btn-outline">Explore {name} ↗</a><a href="#inquiry" class="text-link" data-inquiry-interest="{name}">Inquire Now ↗</a></div></article>'
mineralbody+='</div><p class="availability-note">Availability and commercial terms are confirmed by the team for each enquiry.</p></div></section>'+form+'</main>'
(root/'minerals.html').write_text(head+'<body class="page-minerals">'+nav.replace(' class="is-active" aria-current="page"','')+mineralbody+footer+'<script src="js/script.js?v=20261008"></script><script src="js/enquiry.js"></script><script src="js/account-menu.js?v=20261009nav"></script></body></html>',encoding='utf-8')
for p in root.glob('*.html'):
 text=p.read_text(encoding='utf-8')
 if 'nav-primary' in text and 'href="minerals.html"' not in text[text.index('<nav'):text.index('</nav>')]:
  text=text.replace('<a href="trade.html">Trade</a>', '<a href="minerals.html"'+(' class="is-active" aria-current="page"' if p.name=='minerals.html' else '')+'>Minerals</a><a href="trade.html">Trade</a>',1)
 if 'css/site-update.css' in text and 'css/content-update.css' not in text:
  text=text.replace('</head>','<link rel="stylesheet" href="css/content-update.css?v=20261010">\n</head>')
 if p.name in ['index.html','contact.html','about.html']:
  if p.name=='contact.html': text=text.replace('<footer',form+'<footer',1)
  text=text.replace('</body>','<script src="js/enquiry.js"></script>\n</body>')
 p.write_text(text,encoding='utf-8')
